"""An episode's instrumental music bed, generated by a local ACE-Step 1.5 REST server.

The cue comes from the project overview (an English caption of genre, mood, instruments and texture, and a tempo)
and the episode's length. The server is asked for an instrumental of the episode's length plus a margin, at a fixed
seed, with its language model off (the caption and tempo are given, so nothing is left for it to plan). Before the
request, the GPU is asked to free other models (ComfyUI ``/free``), since the music model shares one card with image
generation. The result is cached under the project by the cue's digest, so a render repeated for the same cue
reuses it.
"""

from __future__ import annotations

import asyncio
import contextlib
import hashlib
import json
import os
from collections.abc import Mapping, Sequence
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

import httpx

#: The episode's music is asked this much longer than the episode; the server's length is a target.
LENGTH_MARGIN_SECONDS = 4.0
MIN_SECONDS = 10.0
MAX_SECONDS = 600.0
SEED = 20261113
POLL_SECONDS = 2.0


class MusicUnavailable(RuntimeError):
    """The music server could not produce the cue."""


@dataclass(frozen=True)
class MusicCue:
    caption: str
    bpm: int
    seconds: float
    seed: int = SEED

    def digest(self) -> str:
        return hashlib.sha256(json.dumps(asdict(self), sort_keys=True).encode()).hexdigest()[:24]


def cue_for(project: Mapping[str, Any], episode_seconds: float) -> MusicCue | None:
    """The episode's cue from the project overview; ``None`` when the overview names no music."""
    overview = project.get("overview")
    if not isinstance(overview, Mapping):
        return None
    caption, bpm = overview.get("music_caption"), overview.get("music_bpm")
    if not isinstance(caption, str) or not caption.strip() or not isinstance(bpm, int):
        return None
    seconds = min(max(episode_seconds + LENGTH_MARGIN_SECONDS, MIN_SECONDS), MAX_SECONDS)
    return MusicCue(caption=caption.strip(), bpm=min(max(bpm, 30), 300), seconds=round(seconds, 1))


class MusicService:
    def __init__(
        self,
        base_url: str,
        *,
        free_urls: Sequence[str] = (),
        timeout_seconds: float = 900.0,
        poll_seconds: float = POLL_SECONDS,
        transport: httpx.AsyncBaseTransport | None = None,
    ) -> None:
        self._base = base_url.rstrip("/")
        self._free_urls = tuple(free_urls)
        self._timeout = timeout_seconds
        self._poll = poll_seconds
        self._transport = transport

    async def render(self, cue: MusicCue, output: Path) -> Path:
        """Generate ``cue`` into ``output`` (WAV); an existing ``output`` is returned as is."""
        if await asyncio.to_thread(output.is_file):
            return output
        async with httpx.AsyncClient(timeout=60.0, transport=self._transport) as client:
            for url in self._free_urls:
                with contextlib.suppress(httpx.HTTPError):
                    await client.post(url, json={"unload_models": True, "free_memory": True})
            try:
                task_id = await self._submit(client, cue)
                audio_path = await self._wait(client, task_id)
                response = await client.get(f"{self._base}{audio_path}")
                response.raise_for_status()
            except httpx.HTTPError as error:
                raise MusicUnavailable(f"music server: {error}") from error
        await asyncio.to_thread(_place, output, response.content)
        return output

    async def _submit(self, client: httpx.AsyncClient, cue: MusicCue) -> str:
        response = await client.post(
            f"{self._base}/release_task",
            json={
                "prompt": cue.caption,
                "lyrics": "[Instrumental]",
                "bpm": cue.bpm,
                "time_signature": "4",
                "audio_duration": cue.seconds,
                "thinking": False,
                "use_cot_caption": False,
                "use_cot_language": False,
                "use_format": False,
                "audio_format": "wav",
                "batch_size": 1,
                "use_random_seed": False,
                "seed": cue.seed,
            },
        )
        response.raise_for_status()
        data = response.json().get("data") or {}
        task_id = data.get("task_id") if isinstance(data, Mapping) else None
        if not isinstance(task_id, str):
            raise MusicUnavailable("music server returned no task id")
        return task_id

    async def _wait(self, client: httpx.AsyncClient, task_id: str) -> str:
        loop = asyncio.get_running_loop()
        deadline = loop.time() + self._timeout
        while loop.time() < deadline:
            response = await client.post(f"{self._base}/query_result", json={"task_id_list": [task_id]})
            response.raise_for_status()
            for item in response.json().get("data") or []:
                if not isinstance(item, Mapping) or item.get("task_id") != task_id:
                    continue
                if item.get("status") == 2:
                    raise MusicUnavailable("music generation failed")
                if item.get("status") == 1:
                    results = json.loads(item.get("result") or "[]")
                    files = [r.get("file") for r in results if isinstance(r, Mapping) and r.get("file")]
                    if not files:
                        raise MusicUnavailable("music result has no file")
                    return str(files[0])
            await asyncio.sleep(self._poll)
        raise MusicUnavailable("music generation timed out")


#: The smallest answer taken for audio: a WAV header plus a few frames.
MIN_WAV_BYTES = 1024


def _place(output: Path, content: bytes) -> None:
    """Cache ``content`` at ``output`` only when it is a WAV file, so a bad answer is never reused."""
    if not content.startswith(b"RIFF") or len(content) < MIN_WAV_BYTES:
        raise MusicUnavailable("music server returned no WAV audio")
    output.parent.mkdir(parents=True, exist_ok=True)
    staging = output.with_name(f"{output.name}.{os.getpid()}.{id(content)}.part")
    staging.write_bytes(content)
    os.replace(staging, output)


def music_service_from_env(environ: Mapping[str, str] | None = None) -> MusicService | None:
    """``ARCREEL_MUSIC_URL`` (the ACE-Step API base) and ``ARCREEL_MUSIC_FREE_URLS`` (comma-separated URLs asked to
    free GPU memory first); ``None`` when no music server is configured."""
    env = os.environ if environ is None else environ
    base = env.get("ARCREEL_MUSIC_URL", "").strip()
    if not base:
        return None
    free = [url.strip() for url in env.get("ARCREEL_MUSIC_FREE_URLS", "").split(",") if url.strip()]
    return MusicService(base, free_urls=free)


__all__ = ["MusicCue", "MusicService", "MusicUnavailable", "cue_for", "music_service_from_env"]
